// David Libre (SIL OFL 1.1) — Hebrew-capable serif fallback for the CV renderer.
// Full Latin + Hebrew coverage; used to draw any string containing Hebrew so the
// codepoint sanitizer no longer strips Hebrew (the modern template's Gelasio has
// no Hebrew glyphs). Regular + Bold only (Hebrew has no italic; the renderer maps
// italic/boldItalic to these). base64-bundled so the renderer has NO runtime
// network fetch, matching the other *-fonts.ts. License: hebrew-fonts-OFL.txt.
// Source: github.com/google/fonts ofl/davidlibre.

const decode = (b64: string): Uint8Array =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const DAVID_REGULAR: Uint8Array = decode(
  "",
);

export const DAVID_BOLD: Uint8Array = decode(
  "",
);
